import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Partial_with_TriageGen1Test {

    @Test(expected = IllegalArgumentException.class)
    public void testWith_NullFieldType_ThrowsException() {
        Partial partial = new Partial();
        partial.with(null, 10);
    }

    @Test
    public void testWith_ExistingField_UpdatesValue() {
        // Setup a partial with Year and Month
        DateTimeFieldType yearType = DateTimeTypes.year();
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();

        Partial partial = new Partial(new DateTimeFieldType[]{yearType, monthType}, new int[]{2020, 1});

        // Change year from 2020 to 2021
        Partial updated = partial.with(yearType, 2021);

        assertEquals(2021, updated.getValue(0));
        assertEquals(1, updated.getValue(1));
        // Ensure it's a new instance (immutability check)
        assert updated != partial;
    }

    @Test
    public void testWith_ExistingField_SameValue_ReturnsThis() {
        DateTimeFieldType yearType = DateTimeTypes.year();
        Partial partial = new Partial(new DateTimeFieldType[]{yearType}, new int[]{2020});

        // Change year to the same value
        Partial updated = partial.with(yearType, 2020);

        // Should return the exact same instance
        assertEquals(partial, updated);
    }

    @Test
    public void testWith_FieldUpdatesCorrectlyViaFieldSetter() {
        // Test with a field that might trigger logic in getField(index).set(...)
        // Using MonthOfYear to ensure we are testing the logic flow
        DateTimeFieldType monthType = DateTimeTypes.monthOfYear();
        Partial partial = new Partial(new DateTimeFieldType[]{monthType}, new int[]{5});

        Partial updated = partial.with(monthType, 12);

        assertEquals(12, updated.getValue(0));
    }

    /**
     * Note: The code contains a 'if (false)' block. 
     * In standard unit testing, code unreachable via static analysis (if false) 
     * cannot be covered. This test focuses on the reachable branches.
     */
}
